//! What the engine returns for a whole program: the `Document` (docs/plan/08-ERRORS.md §5),
//! serialized to JSON for the UI. TypeScript types are generated by ts-rs.
//!
//! Positions are converted from Rust's byte offsets to UTF-16 offsets, which is what JavaScript
//! strings (and CodeMirror) count in. "Σ" is 2 bytes but 1 UTF-16 unit, so this matters.

use delta_core::simulate::RunView;
use delta_core::view::{MachineView, TraceView};
use serde::Serialize;
use ts_rs::TS;

/// The definition a diagnostic cites.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct BookRefView {
    pub item: String,
    pub quote: String,
}

/// Replace [from, to) with `insert`.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct EditView {
    pub from: u32,
    pub to: u32,
    pub insert: String,
}

/// A quick fix.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct FixView {
    pub title: String,
    pub edits: Vec<EditView>,
}

/// A diagnostic, positioned in UTF-16 units.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct DiagnosticView {
    pub code: String,
    /// "error" | "warning" | "info" | "hint"
    pub severity: String,
    pub from: u32,
    pub to: u32,
    pub message: String,
    pub book: Option<BookRefView>,
    pub fixes: Vec<FixView>,
}

/// A named object of the program.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct ObjectView {
    pub name: String,
    /// "dfa" | "nfa" | "gnfa" | "regex"
    pub kind: String,
    /// Where it is declared (the whole statement).
    pub from: u32,
    pub to: u32,
    /// For objects made by `let`: how, e.g. "dfa(N) · subset construction (Theorem 1.39)".
    pub derived: Option<String>,
    pub machine: Option<MachineView>,
    /// For regular expressions: the expression printed with minimal parentheses.
    pub regex: Option<String>,
    pub sigma: Vec<String>,
    pub trace: Option<TraceView>,
}

/// One case of a `check` command.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct CheckCaseView {
    pub input: String,
    pub expected: bool,
    pub actual: bool,
    pub from: u32,
    pub to: u32,
}

/// The output of a `check` or `run` command.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct CommandResultView {
    /// "check" | "run"
    pub kind: String,
    pub object: String,
    pub from: u32,
    pub to: u32,
    pub cases: Vec<CheckCaseView>,
    pub run: Option<RunView>,
}

/// An entry of the outline: what a statement declares, even when it has errors (for completion).
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct OutlineView {
    pub name: String,
    pub kind: String,
    pub from: u32,
    pub to: u32,
    pub states: Vec<String>,
    pub symbols: Vec<String>,
}

/// Everything the UI needs after the user types.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct Document {
    pub objects: Vec<ObjectView>,
    pub diagnostics: Vec<DiagnosticView>,
    pub results: Vec<CommandResultView>,
    pub outline: Vec<OutlineView>,
    /// "strict" | "lenient"
    pub mode: String,
}

/// The result of an interactive run from the Run panel.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct RunResult {
    pub run: Option<RunView>,
    pub error: Option<String>,
}

/// Maps byte offsets of a source string to UTF-16 offsets.
// A plain struct with a private field: other modules can only use it through its methods.
pub struct Utf16Map {
    // offsets[b] = UTF-16 offset of byte b (for every byte, including inside characters).
    offsets: Vec<u32>,
}

impl Utf16Map {
    /// Builds the map for `src`.
    pub fn new(src: &str) -> Utf16Map {
        let mut offsets = Vec::with_capacity(src.len() + 1);
        let mut u = 0u32;
        for c in src.chars() {
            // `0..n` is a range; `_` ignores the loop variable.
            for _ in 0..c.len_utf8() {
                offsets.push(u);
            }
            u += c.len_utf16() as u32;
        }
        offsets.push(u);
        Utf16Map { offsets }
    }

    /// The UTF-16 offset of a byte offset (clamped to the end of the text).
    pub fn get(&self, byte: u32) -> u32 {
        self.offsets
            .get(byte as usize)
            .or_else(|| self.offsets.last())
            .copied()
            .unwrap_or(0)
    }
}
